def next_smallest_palindrome(num):
    num_str = str(num)
    length = len(num_str)

    # Function to check if a number is a palindrome
    def is_palindrome(n):
        return str(n) == str(n)[::-1]

    # Start checking from the next number
    for i in range(num + 1, 10**length):
        if is_palindrome(i):
            return i
