def next_smallest_palindrome(num):
    num_str = str(num)
    length = len(num_str)

    # Function to check if a number is a palindrome
    def is_palindrome(n):
        return str(n) == str(n)[::-1]

    # Handle special case where num is 999...999
    if all(c == '9' for c in num_str):
        return 10 ** length + 1

    # Start checking from num + 1
    for i in range(num + 1, 10 ** length):
        if is_palindrome(i):
            return i
```

