def kth_element(arr, k):
  # Perform selection sort to find the kth smallest element
  for i in range(k-1):
    min_index = i
    for j in range(i+1, len(arr)):
      if arr[j] < arr[min_index]:
        min_index = j
    arr[i], arr[min_index] = arr[min_index], arr[i]
  return arr[k-1]
```

