import math

def div_sum(n):
    if n == 1:
        return 1
    total = 1
    i = 2
    while i * i <= n:
        if n % i == 0:
            if i == n // i:
                total += i
            else:
                total += i + n // i
        i += 1
    return total

def are_equivalent(num1, num2):
    return div_sum(num1) == div_sum(num2)
```

