def is_woodall(x): 
    if x == 1: 
        return True
    if x % 2 == 0: 
        return False
    x = x + 1 
    p = 0
    while (x % 2 == 0): 
        x = x // 2
        p = p + 1
        if p == x: 
            return True
    return False
```

