def is_majority(arr, n, x):
    # Find the first occurrence of x using binary search
    left = 0
    right = n - 1
    first = -1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == x:
            first = mid
            right = mid - 1
        elif arr[mid] < x:
            left = mid + 1
        else:
            right = mid - 1

    # If x is not present, return False
    if first == -1:
        return False

    # Check if the element at position first + n//2 is x
    # If yes, then x is the majority element
    if first + n // 2 < n and arr[first + n // 2] == x:
        return True
    else:
        return False
```

