def get_total_number_of_sequences(m, n):
    # dp[i][j] represents the number of sequences of length j with elements <= i
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(1, m + 1):
        dp[i][1] = i  # sequences of length 1 can be any number from 1 to i

    for j in range(2, n + 1):
        for i in range(1, m + 1):
            # The last element can be any number from ceil(i/2) to i
            # So we add the number of sequences of length j-1 with max element <= i//2
            dp[i][j] = dp[i//2][j-1]

    return dp[m][n]
```

