def get_total_number_of_sequences(m, n):
    # dp[i][j] represents the number of sequences of length j
    # where the last element is at most i
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(m + 1):
        for j in range(n + 1):
            if j == 0:
                dp[i][j] = 1  # One way to have a sequence of length 0 (empty sequence)
            elif j == 1:
                dp[i][j] = i  # All numbers from 1 to i can be the single element
            else:
                # For sequences of length j, the last element can be from 1 to m
                # The previous element must be <= last_element // 2
                # So we sum all possibilities for last_element from 1 to m
                dp[i][j] = sum(dp[k][j-1] for k in range(1, i+1) if k >= 2 * (1 if j-1 == 1 else 0))
    return dp[m][n]
