def get_total_number_of_sequences(m, n):
    # dp[i][j] represents the number of sequences of length j ending with i
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(1, m + 1):
        dp[i][1] = 1  # A sequence of length 1 can only be [i]

    for length in range(2, n + 1):
        for last in range(1, m + 1):
            # The previous element must be <= last / 2
            prev_max = last // 2
            # Sum all sequences of length-1 ending with values <= prev_max
            dp[last][length] = sum(dp[i][length - 1] for i in range(1, prev_max + 1))

    # Total sequences of length n is sum of all sequences ending with any value <= m
    return sum(dp[i][n] for i in range(1, m + 1))
