def get_total_number_of_sequences(m, n):
    # Initialize a 2D DP table where dp[i][j] represents the number of sequences
    # of length j that end with a number <= i
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Base case: sequences of length 1 can end with any number from 1 to i
    for i in range(1, m + 1):
        dp[i][1] = i

    # Fill the DP table
    for length in range(2, n + 1):
        for last in range(1, m + 1):
            # The previous number must be <= last // 2
            prev_max = last // 2
            if prev_max >= 1:
                dp[last][length] = dp[last][length - 1] + dp[prev_max][length - 1]
            else:
                dp[last][length] = dp[last][length - 1]

    # The answer is the total number of sequences of length n with all elements <= m
    return dp[m][n]
