def get_total_number_of_sequences(m, n): 
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(m + 1):
        for j in range(n + 1):
            if j == 0:
                dp[i][j] = 1  # One way to have a sequence of length 0 (empty sequence)
            elif j == 1:
                dp[i][j] = i  # Any number from 1 to i can be the single element
            else:
                # For sequences of length j, the last element can be any value from 1 to m
                # The previous element must be <= last_element // 2
                # So we sum all possibilities where the last element is k (1 <= k <= m)
                # and the previous part is a sequence of length j-1 with max value <= k//2
                total = 0
                for k in range(1, m + 1):
                    total += dp[k // 2][j - 1]
                dp[i][j] = total
    return dp[m][n]
