def max_sum(arr): 
    n = len(arr)
    if n == 0:
        return 0

    # Initialize two arrays
    inc = [0] * n
    dec = [0] * n

    # Compute increasing subsequence sums
    for i in range(n):
        inc[i] = arr[i]
        for j in range(i):
            if arr[j] < arr[i]:
                inc[i] = max(inc[i], inc[j] + arr[i])

    # Compute decreasing subsequence sums from the end
    for i in range(n-1, -1, -1):
        dec[i] = arr[i]
        for j in range(i+1, n):
            if arr[j] < arr[i]:
                dec[i] = max(dec[i], dec[j] + arr[i])

    # Find the maximum bitonic sum
    max_bitonic = 0
    for i in range(n):
        max_bitonic = max(max_bitonic, inc[i] + dec[i] - arr[i])

    return max_bitonic
```

