				MSDBS[-i] = MSDBS[-j] + arr[-i] 
	max_sum = float("-Inf") 
	for i, j in zip(MSIBS, MSDBS): 
		max_sum = max(max_sum, i + j - arr[-1]) 
	return max_sum
